SELECT p.gender, p.age, i.icustay_id, i.intime, i.outtime, i.los, d.interpretation, COUNT(p.subject_id) OVER (PARTITION BY p.subject_id, i.icustay_id, i.intime, i.outtime, i.los, d.interpretation ORDER BY p.subject_id) AS procedure_count, COUNT(p.subject_id) OVER (PARTITION BY p.subject_id, i.icustay_id, i.intime, i.outtime, i.los, d.interpretation ORDER BY p.subject_id ROWS BETWEEN UNBOUNDED preceding AND CURRENT ROW) AS procedure_count_within_first_24_hours, percent_rank() OVER (PARTITION BY p.subject_id ORDER BY p.dod) AS mortality_percentage_rank FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN diagnoses_icd d ON p.subject_id = d.subject_id AND d.icd_code = 'UGIB' WHERE p.age BETWEEN 48 AND 58 AND p.gender = 'M' AND d.interpretation = 'S' AND i.intime <= '2020-01-01' AND (i.outtime >= '2020-01-01' OR i.outtime IS NULL) AND (p.dod >= '2020-01-01' OR p.dod IS NULL) AND (i.los >= 0 OR i.los IS NULL) ORDER BY p.subject_id, procedure_count_within_first_24_hours NULLS LAST;